package app.runeshare.ui;

import app.runeshare.RuneShareConfig;
import app.runeshare.RuneShareSessionTracker;
import app.runeshare.api.*;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.Color;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.List;

@Slf4j
public class RuneSharePluginPanel extends PluginPanel {
    private static final String MAIN_TITLE = "RuneShare";

    private static final String BANK_TABS_TITLE = "Bank Tabs";

    private static final String TASK_SESSIONS_TITLE = "Task Sessions";

    @NonNull
    private final RuneShareConfig runeShareConfig;

    @NonNull
    private final RuneShareApi runeShareApi;

    @NonNull
    private final RuneShareSessionTracker runeShareSessionTracker;

    private TagTab activeTagTab = null;

    private List<Integer> activeItemIds = null;

    private Layout activeLayout = null;

    private NPC activeNpc = null;

    private Integer activeWorldMapXCoordinate = null;

    private Integer activeWorldMapYCoordinate = null;

    private Integer activeTaskSessionId = null;

    public RuneSharePluginPanel(@NonNull RuneShareConfig runeShareConfig, @NonNull RuneShareApi runeShareApi, @NonNull RuneShareSessionTracker runeShareSessionTracker) {
        super(true);

        this.runeShareConfig = runeShareConfig;
        this.runeShareApi = runeShareApi;
        this.runeShareSessionTracker = runeShareSessionTracker;

        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setLayout(new BorderLayout());

        drawPanel();
    }

    public void updateActiveTag(@Nullable TagTab activeTagTab, @Nullable List<Integer> activeItemIds, @Nullable Layout activeLayout) {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(() -> updateActiveTag(activeTagTab, activeItemIds, activeLayout));
            return;
        }

        this.activeTagTab = activeTagTab;
        this.activeLayout = activeLayout;
        this.activeItemIds = activeItemIds;

        if (activeTagTab != null) {
            log.debug("Redrawing panel with \"{}\" tag", activeTagTab.getTag());
        } else {
            log.debug("Redrawing panel without a tag");
        }

        drawPanel();
    }

    public void updateNpc(NPC npc, @Nullable Integer x, @Nullable Integer y) {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(() -> updateNpc(npc, x, y));
            return;
        }

        if (this.activeNpc != npc) {
            this.activeNpc = npc;
            this.activeWorldMapXCoordinate = x;
            this.activeWorldMapYCoordinate = y;

            drawPanel();
        }
    }

    /**
     * Forgets any location captured before the player opted out of sharing it.
     * The panel never renders the coordinates, so there is nothing to redraw.
     */
    public void clearLocation() {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(this::clearLocation);
            return;
        }

        this.activeWorldMapXCoordinate = null;
        this.activeWorldMapYCoordinate = null;
    }

    public void redraw() {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(this::redraw);
            return;
        }

        log.debug("Redrawing panel");
        drawPanel();
    }

    /**
     * A section heading, styled like the ones RuneLite uses for config sections:
     * bold orange text above a divider line.
     */
    private JPanel createSectionHeader(String text) {
        final JLabel label = new JLabel(text);
        label.setForeground(ColorScheme.BRAND_ORANGE);
        label.setFont(FontManager.getRunescapeBoldFont());

        final JPanel header = new JPanel(new BorderLayout());
        header.setBorder(new CompoundBorder(
                new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
                new EmptyBorder(0, 0, 3, 0)));
        header.add(label, BorderLayout.WEST);
        fullWidth(header);

        return header;
    }

    /**
     * The panel's read-only body text. JTextArea rather than JLabel so that long
     * messages wrap to the panel width instead of being clipped.
     * <p>
     * Deliberately not passed through {@link #fullWidth}: a wrapping text area's
     * preferred height depends on the width it ends up with, so pinning its
     * maximum height to the value known at build time would cut off the later
     * lines of a message that wraps. It stretches to the panel width on its own,
     * so it only needs the alignment.
     */
    private JTextArea createBodyText(String text) {
        final JTextArea textArea = new JTextArea(text);
        textArea.setWrapStyleWord(true);
        textArea.setLineWrap(true);
        textArea.setOpaque(false);
        textArea.setEditable(false);
        textArea.setFocusable(false);
        textArea.setAlignmentX(Component.LEFT_ALIGNMENT);

        return textArea;
    }

    /**
     * Stretch a component across the panel.
     * <p>
     * BoxLayout lays children out at their preferred width and then aligns them
     * against each other by alignmentX, so a narrow child sits inset from the
     * panel edge rather than flush against it, no matter what alignment it is
     * given. Letting each child grow to the full width removes the difference
     * the alignment would otherwise be resolving, which left-aligns the text and
     * lets a button's label use the whole width instead of truncating.
     */
    private void fullWidth(JComponent component) {
        component.setAlignmentX(Component.LEFT_ALIGNMENT);
        component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
    }

    private void drawPanel() {
        final JPanel containerPanel = new JPanel();
        containerPanel.setLayout(new BoxLayout(containerPanel, BoxLayout.Y_AXIS));
        containerPanel.setBorder(new EmptyBorder(10, 10, 10, 10));
        containerPanel.setVisible(true);

        final JLabel title = new JLabel(MAIN_TITLE);
        title.setForeground(Color.WHITE);
        title.setFont(FontManager.getRunescapeBoldFont());
        fullWidth(title);
        containerPanel.add(title);

        final String apiToken = runeShareConfig.apiToken();
        final boolean noApiTokenConfigured = apiToken == null || apiToken.isEmpty();
        if (noApiTokenConfigured) {
            containerPanel.add(Box.createVerticalStrut(10));
            containerPanel.add(createBodyText("There is no API token configured. Please add this to the RuneShare plugin settings."));

            finishPanel(containerPanel);
            return;
        }

        containerPanel.add(Box.createVerticalStrut(12));
        containerPanel.add(createSectionHeader(BANK_TABS_TITLE));
        containerPanel.add(Box.createVerticalStrut(6));
        addBankTabsSection(containerPanel);

        containerPanel.add(Box.createVerticalStrut(16));
        containerPanel.add(createSectionHeader(TASK_SESSIONS_TITLE));
        containerPanel.add(Box.createVerticalStrut(6));
        addTaskSessionsSection(containerPanel);

        finishPanel(containerPanel);
    }

    private void addBankTabsSection(JPanel containerPanel) {
        if (this.activeTagTab == null) {
            containerPanel.add(createBodyText("There is no active tag. Please select an tag in your bank."));
            return;
        }

        containerPanel.add(createBodyText("Active Tag: " + this.activeTagTab.getTag()));

        if (runeShareConfig.autoSave()) {
            containerPanel.add(Box.createVerticalStrut(4));
            containerPanel.add(createBodyText("Active tags are being saved automatically to RuneShare."));
            return;
        }

        final JButton syncButton = new JButton("Sync to RuneShare");
        syncButton.addActionListener((event) -> {
            runeShareApi.createRuneShareBankTab(activeTagTab, activeItemIds, activeLayout);
        });
        fullWidth(syncButton);

        containerPanel.add(Box.createVerticalStrut(6));
        containerPanel.add(syncButton);
    }

    private void addTaskSessionsSection(JPanel containerPanel) {
        if (activeNpc == null) {
            containerPanel.add(createBodyText("Start fighting an NPC to start tracking."));
            return;
        }

        if (activeTaskSessionId == null) {
            final JButton startSessionButton = new JButton("Start Session");
            startSessionButton.addActionListener((event) -> {
                final StartTaskSession startTaskSession = StartTaskSession
                        .builder()
                        .npcRunescapeId(activeNpc.getId())
                        .worldMapXCoordinate(activeWorldMapXCoordinate)
                        .worldMapYCoordinate(activeWorldMapYCoordinate)
                        .build();

                runeShareSessionTracker.start(startTaskSession, startTaskSessionResponse -> {
                    this.activeTaskSessionId = startTaskSessionResponse.getTaskSessionId();
                    this.redraw();
                });
            });
            fullWidth(startSessionButton);
            containerPanel.add(startSessionButton);
        } else {
            final JButton stopSessionButton = new JButton("Stop Session");
            stopSessionButton.addActionListener((event) -> {
                runeShareSessionTracker.stop(() -> {
                    this.activeTaskSessionId = null;
                    this.redraw();
                });
            });
            fullWidth(stopSessionButton);
            containerPanel.add(stopSessionButton);
        }
    }

    private void finishPanel(JPanel containerPanel) {
        removeAll();
        add(containerPanel, BorderLayout.NORTH);
        revalidate();
        repaint();
    }
}

package app.runeshare;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import static app.runeshare.RuneShareConfig.CONFIG_GROUP;

@ConfigGroup(CONFIG_GROUP)
public interface RuneShareConfig extends Config
{
	String CONFIG_GROUP = "RuneShare";
	String API_TOKEN_CONFIG_KEY = "apiToken";

	@ConfigItem(
			keyName = API_TOKEN_CONFIG_KEY,
			name = "API Token",
			description = "Your unique API token for your RuneShare account. Go to https://osrs.runeshare.app/api_tokens to create one."
	)
	default String apiToken() { return null; }

	@ConfigItem(
			keyName = "autoSave",
			name = "Auto Save?",
			description = "If checked, changes to Bank Tag Tabs will automatically be saved in RuneShare."
	)
	default boolean autoSave() { return false; }

	@ConfigItem(
			keyName = "shareLocation",
			name = "Share Location?",
			description = "If checked, the world map location where a task session started will be shared with RuneShare."
	)
	default boolean shareLocation() { return true; }
}

package app.runeshare;

import app.runeshare.api.RuneShareApi;
import app.runeshare.ui.RuneSharePluginPanel;
import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.*;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.plugins.xptracker.XpTrackerService;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

@Slf4j
@PluginDescriptor(
	name = "RuneShare",
	description = "Share bank tabs with other players",
	tags = { "gear", "inventory", "setups" }
)
@PluginDependency(BankTagsPlugin.class)
@PluginDependency(XpTrackerPlugin.class)
public class RuneSharePlugin extends Plugin
{
	private static final int NAVIGATION_PRIORITY = 100;
	private static final String PLUGIN_NAME = "RuneShare";
	private static final long TIME_BETWEEN_TASK_EVENTS_MS = 30 * 1000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private RuneShareConfig runeShareConfig;

	@Inject
	private TabManager tabManager;

	@Inject
	private TagManager tagManager;

	@Inject
	private BankTagsService bankTagsService;

	@Inject
	private RuneShareApi runeShareApi;

	@Inject
	private XpTrackerService xpTrackerService;

	private RuneSharePluginPanel panel;

	private NavigationButton navigationButton;

	private String activeTag = null;

	private Layout activeLayout = null;

	private List<Integer> activeItemIds = null;

	private RuneShareSessionTracker runeShareSessionTracker = null;

	private Long lastTaskEventSentAtMs = null;

	@Override
	protected void startUp() throws Exception
	{
		runeShareSessionTracker = new RuneShareSessionTracker(runeShareApi);

		// startUp runs on the EDT when the plugin is toggled on, but reading the
		// account type varbit asserts it is on the client thread. Returning false
		// re-queues this for the next tick, so it retries until we are logged in
		// and the varbit and world type are actually meaningful.
		clientThread.invokeLater(() -> {
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return false;
			}

			updateAccountAndWorld();
			return true;
		});

		this.panel = new RuneSharePluginPanel(runeShareConfig, runeShareApi, runeShareSessionTracker);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		this.navigationButton = NavigationButton.builder()
				.tooltip(PLUGIN_NAME)
				.icon(icon)
				.priority(NAVIGATION_PRIORITY)
				.panel(this.panel)
				.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		// shutDown still runs if startUp threw before the button was built.
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(RuneShareConfig.CONFIG_GROUP)) {
			final boolean shareLocation = runeShareConfig.shareLocation();
			SwingUtilities.invokeLater(() -> {
				// Coordinates are only refreshed when the NPC changes, so drop any
				// that were cached before the player opted out.
				if (!shareLocation) {
					this.panel.clearLocation();
				}
				this.panel.redraw();
			});
		}
	}

	@Subscribe
	public void onWorldChanged(WorldChanged event)
	{
		if (runeShareSessionTracker != null) {
			updateAccountAndWorld();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied hitsplatApplied)
	{
		Actor actor = hitsplatApplied.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}

		final Hitsplat hitsplat = hitsplatApplied.getHitsplat();
		final NPC npc = (NPC) actor;

		boolean weAreAttacking = hitsplat.isMine();
		if (weAreAttacking)
		{
			log.debug("You are attacking {}", npc.getName());

			// The location is best effort: the player, or their location, can be
			// absent, and the session is still worth tracking without coordinates.
			// Players can also opt out of sharing it entirely, in which case we
			// never read it in the first place.
			Integer x = null;
			Integer y = null;
			if (runeShareConfig.shareLocation())
			{
				final Player localPlayer = client.getLocalPlayer();
				final WorldPoint playerLocation = localPlayer == null ? null : localPlayer.getWorldLocation();
				final WorldPoint localWorld = playerLocation == null ? null : WorldPoint.getMirrorPoint(playerLocation, true);
				x = localWorld == null ? null : localWorld.getX();
				y = localWorld == null ? null : localWorld.getY();
			}

			this.panel.updateNpc(npc, x, y);

			long currentTimeInMs = System.currentTimeMillis();
			if (runeShareSessionTracker.isRunning() && (lastTaskEventSentAtMs == null || lastTaskEventSentAtMs + TIME_BETWEEN_TASK_EVENTS_MS < currentTimeInMs)) {
				final int attackXp = client.getSkillExperience(Skill.ATTACK);
				final int strengthXp = client.getSkillExperience(Skill.STRENGTH);
				final int defenceXp = client.getSkillExperience(Skill.DEFENCE);
				final int rangedXp = client.getSkillExperience(Skill.RANGED);
				final int magicXp = client.getSkillExperience(Skill.MAGIC);
				final int hitpointsXp = client.getSkillExperience(Skill.HITPOINTS);
				final int slayerXp = client.getSkillExperience(Skill.SLAYER);

				SwingUtilities.invokeLater(() -> {
					runeShareSessionTracker.updateXp(attackXp, strengthXp, defenceXp, rangedXp, magicXp, hitpointsXp, slayerXp);
				});

				lastTaskEventSentAtMs = currentTimeInMs;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		String tag = bankTagsService.getActiveTag();

		if (tag == null) {
			if (this.activeTag != null) {
				this.activeTag = null;
				this.activeItemIds = null;
				this.activeLayout = null;

				log.debug("There is no longer an active tag");

				SwingUtilities.invokeLater(() -> {
					this.panel.updateActiveTag(null, null, null);
				});
			}
			return;
		}

		List<Integer> itemIds = tagManager.getItemsForTag(tag);
		Layout layout = bankTagsService.getActiveLayout();

		boolean hasTagChanged = !tag.equals(this.activeTag);
		boolean hasItemIdsChanged = activeItemIds != null && !itemIds.isEmpty() && !itemIds.equals(activeItemIds);
		boolean hasLayoutChanged = (layout != null && activeLayout == null) || (layout == null && activeLayout != null) || (layout != null && activeLayout != null && !Arrays.equals(layout.getLayout(), activeLayout.getLayout()));

		if (hasTagChanged || hasItemIdsChanged || hasLayoutChanged) {
			this.activeTag = tag;
			this.activeItemIds = new ArrayList<>(itemIds);

			if (layout != null) {
				this.activeLayout = new Layout(layout);
			} else {
				this.activeLayout = null;
			}

			log.debug("Active tag has changed to \"{}\"", this.activeTag);

			TagTab activeTagTab = tabManager.find(this.activeTag);
			final List<Integer> itemIdsCopy = this.activeItemIds;
			final Layout layoutCopy = this.activeLayout;

			SwingUtilities.invokeLater(() -> {
				final String apiToken = runeShareConfig.apiToken();
				if (activeTagTab != null && apiToken != null && !apiToken.isEmpty() && runeShareConfig.autoSave()) {
					log.info("Automatically saving bank tab to RuneShare.");
					runeShareApi.createRuneShareBankTab(activeTagTab, itemIdsCopy, layoutCopy);
				}

				this.panel.updateActiveTag(activeTagTab, itemIdsCopy, layoutCopy);
			});
		}
	}

	@Provides
	RuneShareConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneShareConfig.class);
	}

	private void updateAccountAndWorld() {
		runeShareSessionTracker.setAccountType(getAccountType());
		runeShareSessionTracker.setWorldTypes(client.getWorldType());
	}

	private String getAccountType() {
		int accountTypeId = client.getVarbitValue(Varbits.ACCOUNT_TYPE);
		String accountType = null;
		if (accountTypeId == 0) {
			accountType = "normal";
		} else if (accountTypeId == 1) {
			accountType = "ironman";
		} else if (accountTypeId == 2) {
			accountType = "ultimate_ironman";
		} else if (accountTypeId == 3) {
			accountType = "hardcore_ironman";
		} else if (accountTypeId == 4) {
			accountType = "group_ironman";
		} else if (accountTypeId == 5) {
			accountType = "hardcore_group_ironman";
		} else if (accountTypeId == 6) {
			accountType = "unranked_group_ironman";
		}
		return accountType;
	}
}

package app.runeshare;

import app.runeshare.api.*;
import lombok.Getter;
import lombok.NonNull;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.WorldType;

import java.util.EnumSet;

@Slf4j
public class RuneShareSessionTracker {

    @NonNull
    private final RuneShareApi runeShareApi;

    @Getter
    private boolean running = false;

    private Integer taskSessionId = null;

    @Setter
    private EnumSet<WorldType> worldTypes = null;

    @Setter
    private String accountType = null;

    public RuneShareSessionTracker(RuneShareApi runeShareApi) {
        this.runeShareApi = runeShareApi;
    }

    public void start(final StartTaskSession startTaskSession, final StartTaskSessionResponseHandler startTaskSessionResponseHandler) {
        startTaskSession.setAccountType(accountType);
        startTaskSession.setLeagues(isLeaguesWorld());
        runeShareApi.startTaskSession(startTaskSession, startTaskSessionResponse -> {
            this.running = true;
            this.taskSessionId = startTaskSessionResponse.getTaskSessionId();
            startTaskSessionResponseHandler.onSuccess(startTaskSessionResponse);
        });
    }

    public void updateXp(int attackXp, int strengthXp, int defenceXp, int rangedXp, int magicXp, int hitpointsXp, int slayerXp) {
        if (!running) {
            return;
        }

        final RuneShareTaskEvent runeShareTaskEvent = RuneShareTaskEvent
                .builder()
                .taskSessionId(this.taskSessionId)
                .attackXp(attackXp)
                .strengthXp(strengthXp)
                .defenceXp(defenceXp)
                .rangedXp(rangedXp)
                .magicXp(magicXp)
                .hitpointsXp(hitpointsXp)
                .slayerXp(slayerXp)
                .build();

        runeShareApi.createTaskEvent(runeShareTaskEvent);
    }

    public void stop(StopTaskSessionResponseHandler stopTaskSessionResponseHandler) {
        this.running = false;

        final StopTaskSession stopTaskSession = StopTaskSession.builder().taskSessionId(this.taskSessionId).build();
        runeShareApi.stopTaskSession(stopTaskSession, stopTaskSessionResponseHandler);
        this.taskSessionId = null;
    }

    private boolean isLeaguesWorld()
    {
        // worldTypes is populated from the client thread, which may not have run
        // yet when a session is started.
        if (worldTypes == null)
        {
            return false;
        }

        return (worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN));
    }
}

